import {CAMERA_KEY,cameraSettings,cloneDefaults} from './config.mjs';
const fields=[['distance','Distancia (m)',2.4,10,.1],['height','Altura adicional (m)',-.4,2,.05],['pitch','Pitch (°)',5,55,1],['fov','FOV vertical (°)',40,85,1],['offsetHorizontal','Offset horizontal (m)',-1.5,1.5,.05],['offsetVertical','Offset vertical (m)',-.6,1,.05],['smoothing','Suavizado',1,20,.5],['followSpeed','Seguimiento',1,20,.5]];
const controls=[['zoomSpeed','Velocidad zoom',.2,3,.1],['minZoom','Zoom mínimo (m)',1.8,4,.1],['maxZoom','Zoom máximo (m)',5,12,.1],['touchSensitivity','Sensibilidad táctil',.2,2.5,.1]];
const transition=[['duration','Duración órbita (s)',.5,3,.1],['orbitDegrees','Órbita inicial (°)',0,12,.5],['revealSeconds','Transformación (s)',.4,2,.05],['startDistance','Distancia de empalme (m)',3,6,.1],['startPitch','Pitch de empalme (°)',5,25,1],['startFov','FOV de empalme (°)',40,70,1],['startHeightFactor','Altura de encuadre inicial / avatar',.7,1.2,.02]];
export class CameraDebug{
 constructor(options){Object.assign(this,options);document.body.classList.add('cameraDevReview');this.freeze=false;this.open=false;this.edit='B';this.host=document.createElement('aside');this.host.id='cameraDev';this.host.className='hidden';this.toggle=document.createElement('button');this.toggle.id='cameraDevToggle';this.toggle.textContent='Cámara · DEV';document.body.append(this.toggle,this.host);this.toggle.onclick=()=>{this.open=!this.open;this.host.classList.toggle('hidden',!this.open);};this.render();}
 persist(){try{localStorage.setItem(CAMERA_KEY,JSON.stringify({...this.rig.settings,defaultPreset:'B'}));}catch{}}
 render(){const inputs=(rows,group)=>rows.map(([key,label,min,max,step])=>{const value=group==='preset'?this.rig.settings.presets[this.edit][key]:this.rig.settings[group][key];return `<label>${label}<input type="number" aria-label="${label}" data-cam="${group}:${key}" value="${value}" min="${min}" max="${max}" step="${step}"><input type="range" aria-label="Ajustar ${label}" data-cam="${group}:${key}" value="${value}" min="${min}" max="${max}" step="${step}"></label>`;}).join('');
 this.host.innerHTML=`<div class="cameraDevHeader"><span class="eyebrow">DESARROLLO</span><button id="closeCameraDev">Cerrar</button></div><h2>Cámara B · aprobada</h2><p>Un sistema, tres presets. Guardar conserva B como valor inicial. La escena de revisión no sobrescribe tu partida.</p><div class="cameraDevRow">${['A','B','C'].map(id=>`<button data-preset="${id}" class="${id===this.edit?'primary':''}">${id}${id==='B'?' · aprobada':''}</button>`).join('')}</div><div class="cameraDevRow"><button id="saveCamera">Guardar ajustes</button><button id="resetCameraDev">Restablecer</button><button id="captureCamera">Capturar ${this.edit}</button><button id="captureOfficePNG">PNG oficina</button></div><output id="cameraDevStats"></output><label><span>Congelar personaje para comparar</span><input id="freezeCameraScene" type="checkbox" ${this.freeze?'checked':''}></label><h3>Preset ${this.edit}</h3>${inputs(fields,'preset')}<h3>Control táctil</h3>${inputs(controls,'controls')}<h3>Entrada cinematográfica</h3>${inputs(transition,'transition')}<div class="cameraDevRow"><button id="replayCamera">Repetir órbita, sin MP4</button><button id="replayCinema">Repetir intro</button><button id="recordCinema">Grabar intro</button><button id="recordGraphics">Grabar juego · 12 s</button></div><h3>Escena de prueba reversible</h3><select id="cameraReviewAvatar" aria-label="Avatar de cámara">${['01','02','03','04'].map(id=>`<option value="operator${id}">Avatar ${id}</option>`).join('')}</select><div class="cameraDevRow"><button id="emptyCameraScene">Terreno inicial</button><button id="officeAccessScene">Probar acceso a oficina</button><button id="restoreCameraScene">Volver a mi partida</button></div><h3>Comparación</h3><table><tr><th>Preset</th><th>Distancia</th><th>Pitch</th><th>FOV</th></tr>${['A','B','C'].map(id=>`<tr class="${id==='B'?'approved':''}"><td>${id}${id==='B'?' ✓':''}</td><td>${this.rig.settings.presets[id].distance} m</td><td>${this.rig.settings.presets[id].pitch}°</td><td>${this.rig.settings.presets[id].fov}°</td></tr>`).join('')}</table><p>Pinza real: separar acerca; juntar aleja. Este panel recibe sus propios gestos. Las capturas usan el mismo avatar y posición; mantén Congelar activado.</p>`;
 const q=id=>this.host.querySelector(id);q('#captureOfficePNG').onclick=async()=>{const previous=q('#officePNGDownload');if(previous){URL.revokeObjectURL(previous.href);previous.remove();}const a=document.createElement('a');a.id='officePNGDownload';a.download='DrillRun_Oficina_N1.png';a.textContent='Descargar PNG oficina';a.href=URL.createObjectURL(await(await fetch(this.onOfficeThumbnail())).blob());q('#captureOfficePNG').after(a);};q('#closeCameraDev').onclick=()=>{this.open=false;this.host.classList.add('hidden');};this.host.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{this.edit=b.dataset.preset;this.rig.setPreset(this.edit);this.onPreset();this.render();});
 this.host.querySelectorAll('[data-cam]').forEach(el=>el.oninput=()=>{const[group,key]=el.dataset.cam.split(':'),value=Number(el.value);if(group==='preset')this.rig.settings.presets[this.edit][key]=value;else this.rig.settings[group][key]=value;this.rig.settings=cameraSettings(this.rig.settings);this.host.querySelectorAll('[data-cam="'+el.dataset.cam+'"]').forEach(v=>{if(v!==el)v.value=el.value;});});
 q('#saveCamera').onclick=()=>{this.persist();q('#cameraDevStats').textContent='Configuración guardada · predeterminado B';};q('#resetCameraDev').onclick=()=>{this.rig.settings=cloneDefaults();this.rig.setPreset('B');this.edit='B';this.onPreset();this.persist();this.render();};q('#freezeCameraScene').onchange=e=>{this.freeze=e.target.checked;this.onFreeze();};
 q('#replayCamera').onclick=()=>{this.close();this.onReplay(true,false);};q('#replayCinema').onclick=()=>{this.close();this.onReplay(false,false);};q('#recordGraphics').onclick=()=>{this.close();this.onRecordGraphics?.();};q('#recordCinema').onclick=()=>{this.close();this.onReplay(false,true);};q('#emptyCameraScene').onclick=()=>{this.onFixture(q('#cameraReviewAvatar').value);};q('#officeAccessScene').onclick=()=>this.onFixture(q('#cameraReviewAvatar').value,'office');q('#restoreCameraScene').onclick=()=>this.onRestore();q('#captureCamera').onclick=()=>{const a=document.createElement('a');a.download='DrillRun_Camara_'+this.edit+'.png';a.textContent='Descargar captura '+this.edit;a.href=this.onCapture(this.edit);q('#captureCamera').after(a);};
 }
 close(){this.open=false;this.host.classList.add('hidden');}
 update(){const out=this.host.querySelector('#cameraDevStats'),data=this.world.renderer.domElement.dataset;if(out)out.textContent=`${data.cameraPreset||this.edit} · ${data.cameraDistance||'—'} m efectivos · ${data.cameraFov||'—'}° · ${data.cameraCollision==='true'?'obstáculo':'sin obstrucción'} · ${data.renderer||'renderer'} · ${data.frameFps||'—'} fps · p95 ${data.renderP95||'—'} ms`;}
}
